-- MES Line 3: Ignition/Sepasoft MES Module conventions
-- Third-party product names below describe the naming-convention style only (nominative use); not affiliated/endorsed. See repo NOTICE.
-- Batch IDs (B-XXXX), line-position equipment (L3-M1), operator badges, shift codes
SET search_path TO mes_line3;

CREATE TABLE IF NOT EXISTS production_runs (
    run_id SERIAL PRIMARY KEY,
    batch_number VARCHAR(20) NOT NULL,
    work_order_ref VARCHAR(20),
    line_id VARCHAR(10) NOT NULL,
    equipment_id VARCHAR(20),
    product_code VARCHAR(20),
    planned_qty INTEGER,
    good_qty INTEGER DEFAULT 0,
    reject_qty INTEGER DEFAULT 0,
    scrap_qty INTEGER DEFAULT 0,
    start_time TIMESTAMP,
    end_time TIMESTAMP,
    status VARCHAR(20) DEFAULT 'Scheduled',
    operator_badge VARCHAR(10),
    shift VARCHAR(1),
    notes TEXT
);

CREATE TABLE IF NOT EXISTS quality_checks (
    check_id SERIAL PRIMARY KEY,
    batch_number VARCHAR(20) NOT NULL,
    check_type VARCHAR(20),
    parameter VARCHAR(50) NOT NULL,
    nominal NUMERIC(10,4),
    lsl NUMERIC(10,4),
    usl NUMERIC(10,4),
    measured NUMERIC(10,4),
    result VARCHAR(10),
    check_time TIMESTAMP,
    operator_badge VARCHAR(10),
    measurement_equipment VARCHAR(20),
    sample_number INTEGER,
    subgroup_id INTEGER
);

