-- ============================================================
-- equipment: the plant MES equipment registry, one row per
-- production_runs.equipment_id. equipment_name is the machine's name;
-- L3-M1's is the same text as cmms_indianapolis assets.description and
-- iot_historian equipment_registry.equipment_name for that machine. The
-- other names are used by no other seeded system.
-- ============================================================
CREATE TABLE IF NOT EXISTS equipment (
    equipment_id    VARCHAR(20)  PRIMARY KEY,
    equipment_name  VARCHAR(120) NOT NULL UNIQUE,
    line_id         VARCHAR(10)  NOT NULL,
    equipment_type  VARCHAR(30),
    status          VARCHAR(15)  DEFAULT 'Active'
);

